//! Localized strings: typed accessors generated by `build.rs` from the
//! shared ARB catalogs (`lib/l10n/app_*.arb` and `lib/l10n/desktop/*.arb`),
//! formatted with the ICU subset in [`icu`] and CLDR plural rules
//! (`intl_pluralrules`).
//!
//! The active [`L10n`] is a GPUI global. The locale follows the system's
//! preferred languages ([`locale::system_languages`]) unless Settings
//! overrides it.

pub mod components;
pub mod icu;
pub mod locale;

use std::sync::Arc;

use gpui_kit::{App, Global};
use intl_pluralrules::{PluralCategory, PluralRuleType, PluralRules};

use icu::{Part, Selector};

include!(concat!(env!("OUT_DIR"), "/l10n_generated.rs"));

/// A placeholder value.
#[derive(Clone, Copy, Debug)]
pub enum Arg<'a> {
    Str(&'a str),
    Int(i64),
    Num(f64),
}

impl Arg<'_> {
    fn render(&self, out: &mut String) {
        match self {
            Self::Str(s) => out.push_str(s),
            Self::Int(n) => out.push_str(&n.to_string()),
            Self::Num(n) => out.push_str(&format_num(*n)),
        }
    }

    fn as_f64(&self) -> Option<f64> {
        match self {
            Self::Int(n) => Some(*n as f64),
            Self::Num(n) => Some(*n),
            Self::Str(s) => s.parse().ok(),
        }
    }
}

/// Whole numbers without a fraction; others with up to six decimals, so a
/// value like `0.001` keeps its digits and float noise (`1.2500000000000002`)
/// does not show.
fn format_num(n: f64) -> String {
    if n.fract() == 0. && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        let s = format!("{n:.6}");
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

/// The strings of one locale.
#[derive(Clone)]
pub struct L10n {
    index: usize,
    rules: Option<Arc<PluralRules>>,
}

impl Global for L10n {}

impl std::fmt::Debug for L10n {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("L10n")
            .field("locale", &self.locale())
            .finish()
    }
}

impl L10n {
    /// `locale` as the catalogs name it (`en`, `zh_Hant`); unknown → English.
    pub fn new(locale: &str) -> Self {
        let index = LOCALES.iter().position(|l| *l == locale).unwrap_or(0);
        let language = LOCALES[index].split('_').next().unwrap_or("en");
        let rules = language
            .parse::<unic_langid::LanguageIdentifier>()
            .ok()
            .and_then(|id| PluralRules::create(id, PluralRuleType::CARDINAL).ok())
            .map(Arc::new);
        Self { index, rules }
    }

    pub fn locale(&self) -> &'static str {
        LOCALES[self.index]
    }

    /// The raw message, falling back to English.
    pub fn message(&self, index: usize) -> &'static str {
        MESSAGES[self.index][index]
            .or(MESSAGES[0][index])
            .unwrap_or_default()
    }

    /// Whether this locale has its own translation of `index`.
    pub fn has(&self, index: usize) -> bool {
        MESSAGES[self.index][index].is_some_and(|m| !m.is_empty())
    }

    fn text(&self, index: usize) -> String {
        self.message(index).to_string()
    }

    fn format(&self, index: usize, args: &[(&str, Arg<'_>)]) -> String {
        let parts = icu::parse(self.message(index));
        let mut out = String::new();
        self.render(&parts, args, None, &mut out);
        out
    }

    fn category(&self, n: f64) -> &'static str {
        let Some(rules) = &self.rules else {
            return if n == 1. { "one" } else { "other" };
        };
        let selected = if n.fract() == 0. {
            rules.select(n as i64)
        } else {
            rules.select(n)
        };
        match selected {
            Ok(PluralCategory::ZERO) => "zero",
            Ok(PluralCategory::ONE) => "one",
            Ok(PluralCategory::TWO) => "two",
            Ok(PluralCategory::FEW) => "few",
            Ok(PluralCategory::MANY) => "many",
            _ => "other",
        }
    }

    fn render(
        &self,
        parts: &[Part],
        args: &[(&str, Arg<'_>)],
        hash: Option<Arg<'_>>,
        out: &mut String,
    ) {
        let find = |name: &str| args.iter().find(|(n, _)| *n == name).map(|(_, a)| *a);
        for part in parts {
            match part {
                Part::Text(t) => out.push_str(t),
                Part::Arg(name) => match find(name) {
                    Some(a) => a.render(out),
                    None => {
                        out.push('{');
                        out.push_str(name);
                        out.push('}');
                    }
                },
                Part::Hash => match hash {
                    Some(a) => a.render(out),
                    None => out.push('#'),
                },
                Part::Plural { arg, branches } => {
                    let value = find(arg);
                    let n = value.and_then(|a| a.as_f64()).unwrap_or(0.);
                    let exact = branches.iter().find(|(s, _)| match s {
                        Selector::Exact(k) => (*k as f64) == n,
                        Selector::Category(_) => false,
                    });
                    let category = self.category(n);
                    let branch = exact
                        .or_else(|| {
                            branches
                                .iter()
                                .find(|(s, _)| matches!(s, Selector::Category(c) if c == category))
                        })
                        .or_else(|| {
                            branches
                                .iter()
                                .find(|(s, _)| matches!(s, Selector::Category(c) if c == "other"))
                        });
                    if let Some((_, body)) = branch {
                        self.render(body, args, value, out);
                    }
                }
                Part::Select { arg, branches } => {
                    let mut key = String::new();
                    if let Some(a) = find(arg) {
                        a.render(&mut key);
                    }
                    let branch = branches
                        .iter()
                        .find(|(s, _)| *s == key)
                        .or_else(|| branches.iter().find(|(s, _)| s == "other"));
                    if let Some((_, body)) = branch {
                        self.render(body, args, hash, out);
                    }
                }
            }
        }
    }
}

/// Reads the active strings.
pub trait ActiveL10n {
    fn l10n(&self) -> &L10n;
}

impl ActiveL10n for App {
    fn l10n(&self) -> &L10n {
        self.global::<L10n>()
    }
}

/// The index of `key` in the generated tables.
pub fn key_index(key: &str) -> Option<usize> {
    KEYS.binary_search(&key).ok()
}

